#!/bin/bash
# Print the tools this demo actually runs, from their own --version output.
#
# judge/VERSIONS.txt is generated by judge/setup.sh; this script re-reads the
# live tools so RECEIPT.md and README.md can quote a measured number instead
# of a remembered one.
set -euo pipefail

INSTALL_DIR="$HOME/tools/bin"
UV="$INSTALL_DIR/uv"

echo "### uv (GitHub release tarball, sha256-pinned)"
echo
echo "\$ uv --version"
if [ -x "$UV" ]; then
    "$UV" --version
else
    echo "uv not installed; run judge/setup.sh"
    exit 1
fi
echo
echo "### pytest (pinned wheels from judge/requirements.txt)"
echo
echo "pytest pins: $(grep -c '^pytest==' "$(dirname "${BASH_SOURCE[0]}")/requirements.txt") file(s)" >&2
for pkg in pytest iniconfig pluggy pygments packaging exceptiongroup tomli \
            typing-extensions; do
    line=$(grep -m1 "^${pkg}==" "$(dirname "${BASH_SOURCE[0]}")/requirements.txt" || true)
    [ -n "$line" ] && echo "${line%% \\*}"
done
echo
echo "### interpreters (uv-managed, pinned by SPEC.md)"
echo
"$UV" python list --only-installed 2>/dev/null || echo "(no uv-managed interpreter yet; run the matrix)"
